class Solution {
    private static final int MOD = 1_000_000_007;

    public int countGoodStrings(int low, int high, int zero, int one) {
        int[] dp = new int[high + 1];
        dp[0] = 1;
        long answer = 0;
        for (int len = 1; len <= high; len++) {
            long ways = 0;
            if (len >= zero) {
                ways += dp[len - zero];
            }
            if (len >= one) {
                ways += dp[len - one];
            }
            dp[len] = (int) (ways % MOD);
            if (len >= low) {
                answer = (answer + dp[len]) % MOD;
            }
        }
        return (int) answer;
    }
}

import java.util.ArrayDeque;

class Solution {
    private static final int MOD = 1_000_000_007;

    public int countGoodStrings(int low, int high, int zero, int one) {
        int[] memo = new int[high + 1];
        byte[] state = new byte[high + 1];
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        state[0] = 1;
        while (!stack.isEmpty()) {
            int len = stack.peek();
            int nextZero = len + zero;
            if (nextZero <= high && state[nextZero] == 0) {
                state[nextZero] = 1;
                stack.push(nextZero);
                continue;
            }
            int nextOne = len + one;
            if (nextOne <= high && state[nextOne] == 0) {
                state[nextOne] = 1;
                stack.push(nextOne);
                continue;
            }
            long total = len >= low ? 1 : 0;
            if (nextZero <= high) {
                total += memo[nextZero];
            }
            if (nextOne <= high) {
                total += memo[nextOne];
            }
            memo[len] = (int) (total % MOD);
            state[len] = 2;
            stack.pop();
        }
        return memo[0];
    }
}

class Solution {
    private static final int MOD = 1_000_000_007;

    public int countGoodStrings(int low, int high, int zero, int one) {
        int[] waysFrom = new int[high + 1];
        for (int len = high; len >= 0; len--) {
            long total = len >= low ? 1 : 0;
            if (len + zero <= high) {
                total += waysFrom[len + zero];
            }
            if (len + one <= high) {
                total += waysFrom[len + one];
            }
            waysFrom[len] = (int) (total % MOD);
        }
        return waysFrom[0];
    }
}

class Solution {
    private static final int MOD = 1_000_000_007;

    public int countGoodStrings(int low, int high, int zero, int one) {
        int window = Math.max(zero, one) + 1;
        int[] dp = new int[window];
        dp[0] = 1;
        long answer = 0;
        for (int len = 1; len <= high; len++) {
            long ways = 0;
            if (len >= zero) {
                ways += dp[(len - zero) % window];
            }
            if (len >= one) {
                ways += dp[(len - one) % window];
            }
            dp[len % window] = (int) (ways % MOD);
            if (len >= low) {
                answer = (answer + dp[len % window]) % MOD;
            }
        }
        return (int) answer;
    }
}
